{
  "passages": [
    {
      "id": "m82",
      "about_topic": true,
      "says": "facts: towing a trailer reduces acceleration and requires more space; rules: check enough time and room before passing, allow more room before returning to the lane, do not cut back too soon"
    },
    {
      "id": "m83",
      "about_topic": true,
      "says": "procedure: signal, pull over, and let other vehicles pass when holding up a line; facts: fast trucks/buses create wind, a passing large bus/truck may whip the trailer; rules: do not brake, steer carefully back into position; fact: a slight speed increase may help"
    }
  ],
  "statements": [
    {
      "id": "s1",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a driver cannot accelerate the vehicle [?as quickly] WHEN the driver is towing a trailer",
      "sources": [
        {
          "id": "m82",
          "quote": "You cannot accelerate as quickly when you are towing a trailer."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "as quickly",
          "note": "No acceleration measure is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s2",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a driver needs [?more] space WHEN the driver is towing a trailer BECAUSE the length of the vehicle is [?much] longer with a trailer attached",
      "sources": [
        {
          "id": "m82",
          "quote": "You also need more space because the length of your vehicle is much longer with a trailer attached."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "more",
          "note": "No amount of extra space is given."
        },
        {
          "code": "J",
          "span": "much",
          "note": "No measure of how much longer is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s3",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"make sure\")",
      "text": "a driver towing a trailer SHOULD make sure the driver has [?enough] time and room to complete the pass WHEN the driver is about to pass another vehicle",
      "sources": [
        {
          "id": "m82",
          "quote": "Before you pass, make sure you have enough time and room to complete the pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "enough",
          "note": "No measure of time or room is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s4",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"allow\")",
      "text": "a driver towing a trailer SHOULD allow [?more] room before moving back to the lane WHEN the driver has passed another vehicle",
      "sources": [
        {
          "id": "m82",
          "quote": "Once you have passed, allow more room before you move back to your lane."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "more",
          "note": "No amount of extra room is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s5",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not\")",
      "text": "a driver towing a trailer SHOULD NOT cut back into the lane [?too soon] WHEN the driver has passed another vehicle BECAUSE it can cause the trailer to sway and make it [?difficult] to control",
      "sources": [
        {
          "id": "m82",
          "quote": "Do not cut back into the lane too soon. This can cause your trailer to sway and make it difficult to control."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "too soon",
          "note": "No timing or distance measure is given."
        },
        {
          "code": "J",
          "span": "difficult",
          "note": "No measure of control difficulty is given."
        }
      ],
      "links": [],
      "note": "The first 'it' in the reason refers to cutting back into the lane too soon."
    },
    {
      "id": "s6",
      "type": "PROCEDURE",
      "force": "ADVISORY",
      "force_from": "imperative steps",
      "text": "TO let the other vehicles pass WHEN the driver is [?holding up a line of traffic] AND the driver is towing a trailer",
      "steps": [
        {
          "n": "1",
          "text": "signal",
          "sources": [
            "m83"
          ]
        },
        {
          "n": "2",
          "text": "pull over",
          "sources": [
            "m83"
          ]
        },
        {
          "n": "3",
          "text": "let the other vehicles pass",
          "sources": [
            "m83"
          ]
        }
      ],
      "sources": [
        {
          "id": "m83",
          "quote": "If you are holding up a line of traffic, signal, pull over and let the other vehicles pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "holding up a line of traffic",
          "note": "No objective measure of when traffic is being held up is given."
        }
      ],
      "links": [],
      "note": "The towing condition comes from the page Towing; the sentence itself does not mention a trailer."
    },
    {
      "id": "s7",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT [?fast-moving] trucks and buses create a strong air disturbance behind them",
      "sources": [
        {
          "id": "m83",
          "quote": "Fast-moving trucks and buses create a strong air disturbance behind them."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "fast-moving",
          "note": "No speed threshold is given."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s8",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT the wall of wind behind a large bus or truck may whip a trailer to the side, pushing it out of control WHEN a large bus or truck passes a driver towing a trailer",
      "sources": [
        {
          "id": "m83",
          "quote": "If a large bus or truck passes you, the wall of wind behind it may whip your trailer to the side, pushing it out of control."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "s9",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not brake\")",
      "text": "a driver towing a trailer SHOULD NOT brake WHEN a large bus or truck passes the driver AND the wall of wind behind it whips the trailer to the side",
      "sources": [
        {
          "id": "m83",
          "quote": "If a large bus or truck passes you, the wall of wind behind it may whip your trailer to the side, pushing it out of control. When you experience this, do not brake."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "s10",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"steer\")",
      "text": "a driver towing a trailer SHOULD [?carefully] steer the vehicle and trailer back into [?position] WHEN a large bus or truck passes the driver AND the wall of wind behind it whips the trailer to the side",
      "sources": [
        {
          "id": "m83",
          "quote": "If a large bus or truck passes you, the wall of wind behind it may whip your trailer to the side, pushing it out of control. When you experience this, do not brake. Carefully steer your vehicle and trailer back into position."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "carefully",
          "note": "No standard for careful steering is given."
        },
        {
          "code": "R",
          "span": "position",
          "note": "The exact lane position is not stated."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s11",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT a [?slight] increase in speed may help WHEN a large bus or truck passes the driver AND the wall of wind behind it whips the trailer to the side",
      "sources": [
        {
          "id": "m83",
          "quote": "If a large bus or truck passes you, the wall of wind behind it may whip your trailer to the side, pushing it out of control. When you experience this, do not brake. Carefully steer your vehicle and trailer back into position. A slight increase in speed may help."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "slight",
          "note": "No amount of speed increase is given."
        }
      ],
      "links": [],
      "note": "\"may help\" states a possibility, not a permission or duty."
    }
  ]
}
